import {validateDraft} from './import-parser.js';import {nextSubjectColor} from './subject-colors.js';
const normalize=value=>String(value||'').trim().toLowerCase().replace(/\s+/g,' ');
function instant(date,time,zone){const target=new Date(date+'T'+time+':00Z');let guess=target;for(let i=0;i<3;i++){const local=new Intl.DateTimeFormat('sv-SE',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(guess).replace(' ','T'),difference=target-new Date(local+'Z');if(!difference)break;guess=new Date(guess.getTime()+difference)}return guess.toISOString()}
export function validateImportOptions(options){if(!options.semester?.trim())return 'Enter a semester name.';if(!/^\d{4}-\d{2}-\d{2}$/.test(options.start)||!/^\d{4}-\d{2}-\d{2}$/.test(options.end))return 'Choose the semester start and end dates.';const duration=new Date(options.end)-new Date(options.start);if(!Number.isFinite(duration)||duration<0)return 'The end date must follow the start date.';if(duration>366*86400000)return 'Choose a date range of up to one year.';try{new Intl.DateTimeFormat('en',{timeZone:options.timezone})}catch{return 'Enter a valid timezone, such as Africa/Cairo.'}return ''}
export function buildImport(workspace,rows,options,{today,makeId=()=>crypto.randomUUID()}={}){const problem=validateImportOptions(options);if(problem)throw Error(problem);const selected=rows.filter(r=>r.include);if(!selected.length)throw Error('Select at least one entry to import.');if(selected.length>300)throw Error('Import up to 300 entries at a time.');for(const row of selected){const issues=validateDraft(row);if(issues.length)throw Error((row.course_code||row.name||'An entry')+': '+issues.join('. '))}const next=structuredClone(workspace),stamp=new Date().toISOString(),owner=next.users[0].id,stats={courses:0,schedules:0,sessions:0,duplicates:0};const record=value=>({id:makeId(),created_at:stamp,...value});
for(const row of selected){let course=next.courses.find(c=>normalize(c.semester)===normalize(options.semester)&&(row.course_code?normalize(c.course_code)===normalize(row.course_code):normalize(c.name)===normalize(row.name)));const existingCourse=Boolean(course);if(!course){course=record({user_id:owner,course_code:row.course_code.trim()||null,name:row.name.trim(),color:nextSubjectColor(next.courses),semester:options.semester.trim(),semester_start:options.start,semester_end:options.end,professor_name:null,professor_email:null,minimum_attendance_percent:75,late_counts_as_present:true,exclude_excused_from_percentage:true,attendance_alert_enabled:true});next.courses.push(course);stats.courses++}if(!row.has_schedule){if(existingCourse)stats.duplicates++;continue;}let room=null;if(row.room.trim()){room=next.rooms.find(r=>normalize(r.room_name)===normalize(row.room)&&normalize(r.building)===normalize(row.building));if(!room){room=record({user_id:owner,room_name:row.room.trim(),building:row.building.trim()||null,campus:null,directions:null});next.rooms.push(room)}}const duplicate=next.schedules.some(s=>s.course_id===course.id&&Number(s.weekday)===Number(row.weekday)&&s.starts_at_local.slice(0,5)===row.starts_at_local&&s.ends_at_local.slice(0,5)===row.ends_at_local&&s.room_id===(room?.id||null)&&normalize(s.title)===normalize(row.title));if(duplicate){stats.duplicates++;continue}const schedule=record({course_id:course.id,room_id:room?.id||null,title:row.title,weekday:Number(row.weekday),starts_at_local:row.starts_at_local,ends_at_local:row.ends_at_local,timezone:options.timezone,repeat_every_weeks:1,effective_from:options.start,effective_until:options.end,is_active:true});next.schedules.push(schedule);stats.schedules++;for(let date=new Date(options.start+'T12:00Z');date<=new Date(options.end+'T12:00Z');date.setUTCDate(date.getUTCDate()+1)){if((date.getUTCDay()||7)!==schedule.weekday)continue;const day=date.toISOString().slice(0,10);next.class_sessions.push(record({course_id:course.id,schedule_id:schedule.id,room_id:schedule.room_id,occurrence_date:day,starts_at:instant(day,schedule.starts_at_local,options.timezone),ends_at:instant(day,schedule.ends_at_local,options.timezone),status:today&&day<today?'completed':'scheduled',notes:''}));stats.sessions++}}
if(next.class_sessions.length>10000||new TextEncoder().encode(JSON.stringify({workspace:next})).length>1950000)throw Error('This import is too large. Choose fewer classes or a shorter semester date range.');return {workspace:next,stats}}
